'use client';
import {
	useState,
	useCallback,
	useMemo,
	useRef,
	createContext,
	useContext,
	Children,
	cloneElement,
	isValidElement,
	useEffect,
	useLayoutEffect,
	Fragment,
	forwardRef,
	type ReactNode,
} from 'react';
import { cn } from '@/utilities/functions';
import { CheckIcon, ChevronDown, ChevronsUpDown, Search } from 'lucide-react';
import {
	useFloating,
	useClick,
	useDismiss,
	useRole,
	useListNavigation,
	useInteractions,
	FloatingFocusManager,
	useTypeahead,
	offset,
	flip,
	size,
	autoUpdate,
	FloatingPortal,
} from '@floating-ui/react';
import { Badge, Loader } from '@/components';
import { nanoid } from 'nanoid';
import { mergeRefs } from '@/components/toaster/utils';
import {
	disabledClassNames,
	optionGroupDividerClassNames,
	optionGroupDividerSizeClassNames,
	selectItemClassNames,
	sizeClassNames,
} from './component-style';
import type {
	OnClick,
	OnKeyDown,
	SelectButtonProps,
	SelectContextValue,
	SelectGetValues,
	SelectOptionProps,
	SelectOptionsProps,
	SelectOptionValue,
	SelectPortalProps,
	SelectProps,
	SelectSizes,
	SelectOptionGroupProps,
} from './select-types';
import { getTextContent } from './utils';
import { useDebouncedCallback } from '@/utilities/hooks';

// Context to manage the state of the select component.
const SelectContext = createContext<SelectContextValue>(
	{} as SelectContextValue
);
const useSelectContext = () => useContext( SelectContext );

export const SelectButton = forwardRef<HTMLElement, SelectButtonProps>(
	(
		{
			children,
			icon = null, // Icon to show in the select button.
			placeholder = 'Select an option', // Placeholder text.
			optionIcon = null, // Icon to show in the selected option.
			render,
			label, // Label for the select component.
			className,
			...props
		}: SelectButtonProps,
		ref
	) => {
		const {
			sizeValue,
			getReferenceProps,
			getValues,
			selectId,
			refs,
			isOpen,
			multiple,
			combobox,
			inlineSearch,
			setSelected,
			onChange,
			isControlled,
			disabled,
			by,
			searchKeyword,
			setSearchKeyword,
			searchPlaceholder,
			context,
			activeIndex,
			optionValuesRef,
			handleSelect,
		} = useSelectContext();

		const badgeSize = {
			sm: 'xs',
			md: 'sm',
			lg: 'md',
		}?.[ sizeValue as SelectSizes ];

		const inputRef = useRef<HTMLInputElement>( null );
		const [ hasTyped, setHasTyped ] = useState( false );
		useEffect( () => {
			if ( ! isOpen ) {
				setHasTyped( false );
			}
		}, [ isOpen ] );

		// For inlineSearch single mode: derive string label of the selected value for input display.
		const singleLabel = useMemo( () => {
			if ( ! inlineSearch || multiple ) {
				return '';
			}
			const val = getValues();
			if ( ! val ) {
				return '';
			}
			if ( typeof render === 'function' ) {
				const rendered = render( val as SelectOptionValue );
				if ( typeof rendered === 'string' ) {
					return rendered;
				}
			}
			if ( typeof val === 'string' || typeof val === 'number' ) {
				return String( val );
			}
			const nameKey = ( val as Record<string, unknown> ).name;
			return typeof nameKey === 'string' ? nameKey : '';
		}, [ inlineSearch, multiple, getValues, render ] );

		// Get icon based on the Select component type and user provided icon.
		const getIcon = useCallback( () => {
			if ( icon ) {
				return icon;
			}

			const iconClassNames =
				'text-field-placeholder ' + disabledClassNames.icon;

			return combobox ? (
				<ChevronsUpDown className={ iconClassNames } />
			) : (
				<ChevronDown className={ iconClassNames } />
			);
		}, [ icon ] );

		const renderSelected = useCallback( () => {
			const selectedValue = getValues();

			if ( ! selectedValue ) {
				return null;
			}

			if ( multiple ) {
				return ( selectedValue as SelectOptionValue[] ).map(
					( valueItem: SelectOptionValue, index: number ) => (
						<Badge
							className="cursor-default"
							icon={ optionIcon }
							type="rounded"
							key={ index }
							size={ badgeSize as SelectSizes }
							onMouseDown={ handleOnCloseItem( valueItem ) }
							label={
								typeof render === 'function'
									? render( valueItem as SelectOptionValue )
									: valueItem.toString()
							}
							closable={ true }
							disabled={ disabled }
						/>
					)
				);
			}

			let renderValue: ReactNode =
				typeof selectedValue === 'string' ? selectedValue : '';

			if ( typeof render === 'function' ) {
				renderValue = render( selectedValue as SelectOptionValue );
			}

			if (
				typeof children === 'function' &&
				typeof render !== 'function'
			) {
				const childProps = {
					value: selectedValue as SelectOptionValue,
					...( multiple
						? {
							onClose: handleOnCloseItem(
									selectedValue as SelectOptionValue
							),
						}
						: {} ),
				};
				renderValue = children( childProps );
			}

			if (
				( isValidElement( children ) || typeof children === 'string' ) &&
				typeof render !== 'function'
			) {
				renderValue = children;
			}

			return (
				<span
					className={ cn(
						'truncate',
						sizeClassNames[ sizeValue as SelectSizes ]
							.displaySelected,
						disabledClassNames.text
					) }
				>
					{ renderValue as React.ReactNode }
				</span>
			);
		}, [ getValues, disabled ] );

		const handleOnCloseItem =
			( value: SelectOptionValue ) =>
				( event?: React.MouseEvent<HTMLElement> ) => {
					event?.preventDefault();
					event?.stopPropagation();

					const selectedValues = [
						...( ( getValues() as SelectOptionValue[] ) ?? [] ),
					];
					const selectedIndex = selectedValues.findIndex( ( val ) => {
						if (
							val !== null &&
						value !== null &&
						typeof val === 'object'
						) {
							return (
								( val as Record<string, unknown> )[ by ] ===
							( value as Record<string, unknown> )[ by ]
							);
						}
						return val === value;
					} );

					if ( selectedIndex === -1 ) {
						return;
					}

					selectedValues.splice( selectedIndex, 1 );

					if ( ! isControlled ) {
						setSelected( selectedValues );
					}
					if ( typeof onChange === 'function' ) {
						onChange( selectedValues );
					}
				};

		if ( inlineSearch ) {
			let inputValue = '';
			if ( ! multiple && getValues() ) {
				// Single with value: show label until user types, then show query.
				inputValue = isOpen && hasTyped ? searchKeyword : singleLabel;
			} else if ( isOpen ) {
				inputValue = searchKeyword;
			}

			const showPlaceholder = multiple
				? ! ( getValues() as SelectOptionValue[] )?.length
				: ! getValues() && ! searchKeyword;

			return (
				<div className="w-full flex flex-col items-start gap-1.5 [&_*]:box-border box-border">
					{ !! label && (
						<label
							className={ cn(
								sizeClassNames[ sizeValue as SelectSizes ]?.label,
								'text-field-label'
							) }
							htmlFor={ selectId }
						>
							{ label }
						</label>
					) }
					{ /* Visual chrome wrapper — POSITION reference only, not the interactive reference */ }
					{ /* eslint-disable-next-line jsx-a11y/no-static-element-interactions */ }
					<div
						ref={ refs.setPositionReference }
						className={ cn(
							'flex flex-wrap items-center justify-between w-full box-border transition-[outline,background-color,color,box-shadow] duration-200 bg-white cursor-text',
							'outline outline-1 outline-field-border border-none',
							'focus-within:ring-2 focus-within:ring-offset-2 focus-within:outline-focus-border focus-within:ring-focus',
							'[&:hover:not(:focus-within):not(:has(:disabled))]:outline-border-strong',
							sizeClassNames[ sizeValue as SelectSizes ]
								.selectButton,
							multiple &&
								sizeClassNames[ sizeValue as SelectSizes ]
									.multiSelect,
							disabledClassNames.selectButton,
							className
						) }
						onMouseDown={ ( e: React.MouseEvent ) => {
							// Click on chrome (badges/padding/icon) → focus input.
							if ( e.target !== inputRef.current ) {
								e.preventDefault();
								inputRef.current?.focus();
							}
						} }
					>
						{ /* Badges + inline input */ }
						<div className="flex-1 flex flex-wrap items-center gap-1.5 overflow-hidden">
							{ multiple && renderSelected() }
							{ /* Input IS the floating-ui interactive reference.
							     useRole adds role/aria-expanded/aria-controls/aria-haspopup.
							     useListNavigation (virtual) adds aria-activedescendant + arrow key nav.
							     useDismiss adds Escape handling. */ }
							<input
								ref={ mergeRefs( refs.setReference, inputRef ) }
								id={ selectId }
								type="text"
								autoComplete="off"
								aria-autocomplete="list"
								disabled={ disabled }
								placeholder={
									showPlaceholder ? searchPlaceholder : ''
								}
								value={ inputValue }
								className={ cn(
									'flex-1 min-w-[4rem] bg-transparent border-0 outline-none focus:ring-0 p-0',
									'placeholder:text-field-placeholder',
									sizeClassNames[ sizeValue as SelectSizes ]
										.displaySelected,
									disabledClassNames.text
								) }
								{ ...getReferenceProps( {
									onFocus: () => {
										if ( ! isOpen ) {
											context.onOpenChange( true );
										}
									},
									onClick: () => {
										if ( ! isOpen ) {
											context.onOpenChange( true );
										}
									},
									onChange: (
										e: React.ChangeEvent<HTMLInputElement>
									) => {
										setHasTyped( true );
										setSearchKeyword( e.target.value );
										if ( ! isOpen ) {
											context.onOpenChange( true );
										}
									},
									onKeyDown: ( e: React.KeyboardEvent ) => {
										if (
											e.key === 'Enter' &&
											activeIndex !== null &&
											activeIndex >= 0
										) {
											e.preventDefault();
											const val =
												optionValuesRef.current[
													activeIndex
												];
											if ( val !== undefined ) {
												handleSelect( activeIndex, val );
											}
											return;
										}
										if (
											e.key === 'Backspace' &&
											! inputValue &&
											multiple
										) {
											e.preventDefault();
											const arr =
												( getValues() as SelectOptionValue[] ) ??
												[];
											if ( arr.length ) {
												handleOnCloseItem(
													arr[ arr.length - 1 ]
												)();
											}
										}
									},
								} ) }
							/>
						</div>
						{ /* Suffix Icon */ }
						<div
							className={ cn(
								'flex items-center [&>svg]:shrink-0',
								sizeClassNames[ sizeValue as SelectSizes ].icon
							) }
						>
							{ getIcon() }
						</div>
					</div>
				</div>
			);
		}

		return (
			<div className="w-full flex flex-col items-start gap-1.5 [&_*]:box-border box-border">
				{ !! label && (
					<label
						className={ cn(
							sizeClassNames[ sizeValue as SelectSizes ]?.label,
							'text-field-label'
						) }
						htmlFor={ selectId }
					>
						{ label }
					</label>
				) }
				<button
					id={ selectId }
					ref={ mergeRefs( refs.setReference, ref ) }
					className={ cn(
						'flex items-center justify-between w-full box-border transition-[outline,background-color,color,box-shadow] duration-200 bg-white',
						'outline outline-1 outline-field-border border-none cursor-pointer',
						! isOpen &&
							'focus:ring-2 focus:ring-offset-2 focus:outline-focus-border focus:ring-focus [&:hover:not(:focus):not(:disabled)]:outline-border-strong',
						sizeClassNames[ sizeValue as SelectSizes ].selectButton,
						multiple &&
							sizeClassNames[ sizeValue as SelectSizes ]
								.multiSelect,
						disabledClassNames.selectButton,
						className
					) }
					tabIndex={ 0 }
					disabled={ disabled }
					{ ...props }
					{ ...getReferenceProps() }
				>
					{ /* Input and selected item container */ }
					<div
						className={ cn(
							'flex-1 grid items-center justify-start gap-1.5 overflow-hidden',
							getValues() && 'flex flex-wrap'
						) }
					>
						{ /* Show Selected item/items (Multi-selector) */ }
						{ renderSelected() }

						{ /* Placeholder */ }
						{ ( multiple
							? ! ( getValues() as SelectOptionValue[] )?.length
							: ! getValues() ) && (
							<div
								className={ cn(
									'[grid-area:1/1/2/3] text-field-input px-1',
									sizeClassNames[ sizeValue as SelectSizes ]
										.displaySelected,
									disabledClassNames.text
								) }
							>
								{ placeholder }
							</div>
						) }
					</div>
					{ /* Suffix Icon */ }
					<div
						className={ cn(
							'flex items-center [&>svg]:shrink-0',
							sizeClassNames[ sizeValue as SelectSizes ].icon
						) }
					>
						{ getIcon() }
					</div>
				</button>
			</div>
		);
	}
);

export function SelectOptionGroup( {
	label,
	children,
	className,
	...props
}: SelectOptionGroupProps ) {
	const { index, totalGroups } = props as {
		index: number;
		totalGroups: number;
	};
	const { sizeValue } = useSelectContext();

	const groupClassNames = {
		sm: 'text-xs',
		md: 'text-xs',
		lg: 'text-sm',
	};

	return (
		<Fragment>
			<div className="flex flex-col" role="group" aria-label={ label }>
				<div
					className={ cn(
						'p-2 font-normal text-text-tertiary',
						groupClassNames[ sizeValue as SelectSizes ],
						className
					) }
					id={ `group-${ label?.toLowerCase().replace( /\s+/g, '-' ) }` }
				>
					{ label }
				</div>
				<div
					className="flex flex-col"
					role="presentation"
					aria-labelledby={ `group-${ label?.toLowerCase().replace( /\s+/g, '-' ) }` }
				>
					{ children }
				</div>
			</div>
			{ index < totalGroups &&
				!! ( children && Children.count( children ) > 0 ) && (
				<hr
					className={ cn(
						optionGroupDividerClassNames,
						optionGroupDividerSizeClassNames[
								sizeValue as SelectSizes
						]
					) }
				/>
			) }
		</Fragment>
	);
}

export function SelectOptions( {
	children,
	className, // Additional class name for the dropdown.
}: SelectOptionsProps ) {
	const {
		isOpen,
		context,
		refs,
		combobox,
		inlineSearch,
		floatingStyles,
		getFloatingProps,
		sizeValue,
		setSearchKeyword,
		setActiveIndex,
		setSelectedIndex,
		value,
		selected,
		getValues,
		searchKeyword,
		listContentRef,
		by,
		searchPlaceholder,
		activeIndex,
		searchFn,
		debounceDelay,
		selectId,
		optionValuesRef,
	} = useSelectContext();

	const initialSelectedValueIndex = useMemo( () => {
		const currentValue = getValues();
		let indexValue = -1;

		if ( currentValue ) {
			// Get all children as an array
			let allChildren = Children.toArray( children );

			// If it's an option group, flatten the children
			if (
				allChildren.length > 0 &&
				isValidElement( allChildren[ 0 ] ) &&
				allChildren[ 0 ].type === SelectOptionGroup
			) {
				allChildren = Children.toArray( children )
					.map( ( group ) =>
						isValidElement( group )
							? Children.toArray( group.props.children )
							: []
					)
					.flat();
			}

			indexValue = allChildren.findIndex( ( child: React.ReactNode ) => {
				if ( ! isValidElement( child ) ) {
					return false;
				}

				const childValue = child.props.value;

				if (
					typeof childValue === 'object' &&
					typeof currentValue === 'object'
				) {
					return (
						childValue[ by ] ===
						( currentValue as Record<string, unknown> )[ by ]
					);
				}

				// For non-object values, do a direct comparison
				return childValue === currentValue;
			} );
		}

		return indexValue;
	}, [ value, selected, children, by ] );

	// Initialize active and selected index.
	useLayoutEffect( () => {
		if ( isOpen ) {
			return;
		}
		setActiveIndex( initialSelectedValueIndex );
		setSelectedIndex( initialSelectedValueIndex );
	}, [ initialSelectedValueIndex, isOpen ] );

	// Reset active index when search keyword changes.
	useLayoutEffect( () => {
		if ( ! isOpen ) {
			return;
		}
		if ( combobox && [ -1, null ].includes( activeIndex ) ) {
			return;
		}
		setActiveIndex( -1 );
	}, [ searchKeyword, isOpen ] );

	// Render children based on the search keyword.
	const renderChildren = useMemo( () => {
		// Track actual visible groups after filtering
		let visibleGroups = 0;
		let totalGroups = 0;

		// First pass - count total visible groups
		Children.forEach( children, ( child ) => {
			if ( isValidElement( child ) && child.type === SelectOptionGroup ) {
				let hasVisibleChildren = false;

				// If there's a search term and no external search function
				if ( searchKeyword && ! searchFn ) {
					const searchTerm = searchKeyword.toLowerCase();
					const groupLabel = child.props.label?.toLowerCase() || '';

					// Check if group label matches search term
					const groupLabelMatches = groupLabel.includes( searchTerm );

					// Check if any child option matches search term
					const hasMatchingChildren = Children.toArray(
						child.props.children
					).some( ( groupChild ) => {
						if ( ! isValidElement( groupChild ) ) {
							return false;
						}

						const textContent = getTextContent(
							groupChild.props.children
						)?.toLowerCase();

						return textContent.includes( searchTerm );
					} );

					// Show group if either group label matches or any child matches
					hasVisibleChildren =
						groupLabelMatches || hasMatchingChildren;
				} else {
					// No search term, show all groups
					hasVisibleChildren = true;
				}

				if ( hasVisibleChildren ) {
					visibleGroups++;
				}
			}
		} );

		totalGroups = Math.max( 0, visibleGroups - 1 ); // Subtract 1 since we don't need divider after last group
		let childIndex = 0;
		let groupIndex = 0;
		optionValuesRef.current = [];

		// Process child to render
		const processChild = ( child: React.ReactNode ): React.ReactNode => {
			if ( ! isValidElement( child ) ) {
				return null;
			}

			// Handle option groups
			if ( child.type === SelectOptionGroup ) {
				let groupLabelMatches = false;

				// Check if group label matches search term
				if ( searchKeyword && ! searchFn ) {
					const searchTerm = searchKeyword.toLowerCase();
					const groupLabel = child.props.label?.toLowerCase() || '';
					groupLabelMatches = groupLabel.includes( searchTerm );
				}

				// Recursively process children of the option group
				const groupChildren = Children.map(
					child.props.children,
					( groupChild ) => {
						if ( ! isValidElement( groupChild ) ) {
							return null;
						}

						// If group label matches, show all children regardless of their content
						if ( groupLabelMatches ) {
							const itemIndex = childIndex++;
							optionValuesRef.current[ itemIndex ] = (
								groupChild.props as SelectOptionProps
							).value;
							const childProps = {
								...( groupChild.props as SelectOptionProps ),
								index: itemIndex,
								id: `${ selectId }-option-${ itemIndex }`,
							};

							return cloneElement( groupChild, childProps );
						}

						// Otherwise, apply normal filtering to individual options
						if ( searchKeyword && ! searchFn ) {
							const textContent = getTextContent(
								(
									groupChild.props as {
										children?: React.ReactNode;
									}
								).children
							)?.toLowerCase();
							const searchTerm = searchKeyword.toLowerCase();

							const textMatch = textContent?.includes( searchTerm );

							if ( ! textMatch ) {
								return null;
							}
						}

						const itemIndex = childIndex++;
						optionValuesRef.current[ itemIndex ] = (
							groupChild.props as SelectOptionProps
						).value;
						const childProps = {
							...( groupChild.props as SelectOptionProps ),
							index: itemIndex,
							id: `${ selectId }-option-${ itemIndex }`,
						};

						return cloneElement( groupChild, childProps );
					}
				);

				// Only render group if it has visible children
				const hasChildren = groupChildren?.some(
					( c: React.ReactNode ) => c !== null
				);

				if ( ! hasChildren ) {
					return null;
				}

				const groupProps = {
					...child.props,
					children: groupChildren,
					index: groupIndex,
					totalGroups,
				};

				groupIndex++;
				return cloneElement( child, groupProps );
			}

			// Handle regular options when searchFn is not provided
			if ( searchKeyword && ! searchFn ) {
				const textContent = getTextContent(
					child.props?.children
				)?.toLowerCase();
				const searchTerm = searchKeyword.toLowerCase();

				const textMatch = textContent?.includes( searchTerm );

				if ( ! textMatch ) {
					return null;
				}
			}

			const itemIndex = childIndex++;
			optionValuesRef.current[ itemIndex ] = child.props.value;
			return cloneElement( child, {
				...child.props,
				index: itemIndex,
				id: `${ selectId }-option-${ itemIndex }`,
			} );
		};

		return Children.map( children, processChild );
	}, [
		searchKeyword,
		value,
		selected,
		children,
		searchFn,
		selectId,
		optionValuesRef,
	] );
	const childrenCount = Children.count( renderChildren );

	// Update the content list reference.
	useEffect( () => {
		listContentRef.current = [];
		// Get all children as an array.
		let allChildren = Children.toArray( children );
		// If it's an option group and has children.
		if (
			allChildren &&
			isValidElement( allChildren[ 0 ] ) &&
			allChildren[ 0 ].type === SelectOptionGroup
		) {
			allChildren = Children.toArray( allChildren )
				.map( ( child ) =>
					isValidElement( child ) ? child.props.children : null
				)
				.filter( Boolean );
		}
		// Update the list content reference.
		Children.forEach( allChildren, ( child ) => {
			if ( ! isValidElement( child ) ) {
				return;
			}

			const textContent = getTextContent(
				child.props?.children
			)?.toLowerCase();
			// Handle regular options when searchFn is not provided
			if ( searchKeyword && ! searchFn ) {
				const searchTerm = searchKeyword.toLowerCase();
				const textMatch = textContent?.includes( searchTerm );

				if ( ! textMatch ) {
					return;
				}
			}

			listContentRef.current.push( textContent );
		} );
	}, [ searchKeyword, searchFn ] );

	const [ searching, setSearching ] = useState( false );

	// Create a function to handle the search function.
	const handleSearchFn = useCallback( async () => {
		if ( ! searchFn || typeof searchFn !== 'function' || searching ) {
			return;
		}

		setSearching( true );
		try {
			await searchFn( searchKeyword );
		} catch ( error ) {
			// eslint-disable-next-line no-console
			console.error( error );
		} finally {
			setSearching( false );
		}
	}, [ searchKeyword ] );

	// Debounce the search function.
	const initiateSearch = useDebouncedCallback( handleSearchFn, debounceDelay! );

	// Initiate search when searchFn is a function.
	useEffect( () => {
		if ( typeof searchFn !== 'function' ) {
			return;
		}
		initiateSearch();
	}, [ initiateSearch ] );

	const dropdownContent = (
		<div
			ref={ refs.setFloating }
			className={ cn(
				'box-border [&_*]:box-border w-full bg-white outline-none shadow-lg outline outline-1 outline-border-subtle',
				combobox &&
					! inlineSearch &&
					'grid grid-cols-1 grid-rows-[auto_1fr] divide-y divide-x-0 divide-solid divide-border-subtle',
				sizeClassNames[ sizeValue as SelectSizes ].dropdown,
				! ( combobox && ! inlineSearch ) && 'h-auto',
				! ( combobox && ! inlineSearch )
					? 'overflow-y-auto overflow-x-hidden'
					: 'overflow-hidden',
				className
			) }
			style={ {
				...floatingStyles,
				zIndex: 1,
			} }
			{ ...getFloatingProps() }
		>
			{ /* Searchbox — combobox only; inlineSearch uses trigger input */ }
			{ combobox && ! inlineSearch && (
				<div
					className={ cn(
						sizeClassNames[ sizeValue as SelectSizes ]
							.searchbarWrapper
					) }
				>
					{ searching ? (
						<Loader
							className={
								sizeClassNames[ sizeValue as SelectSizes ]
									.searchbarIcon
							}
						/>
					) : (
						<Search
							className={ cn(
								'text-icon-secondary shrink-0',
								sizeClassNames[ sizeValue as SelectSizes ]
									.searchbarIcon
							) }
						/>
					) }
					<input
						className={ cn(
							'px-1 w-full placeholder:text-field-placeholder border-0 focus:outline-none focus:shadow-none',
							sizeClassNames[ sizeValue as SelectSizes ].searchbar
						) }
						type="search"
						name="keyword"
						aria-label="Search options"
						placeholder={ searchPlaceholder }
						onChange={ ( event ) =>
							setSearchKeyword( event.target.value )
						}
						value={ searchKeyword }
						autoComplete="off"
					/>
				</div>
			) }
			{ /* Dropdown Items Wrapper */ }
			<div
				className={ cn(
					'overflow-y-auto overflow-x-hidden',
					! ( combobox && ! inlineSearch ) && 'w-full h-full',
					sizeClassNames[ sizeValue as SelectSizes ]
						.dropdownItemsWrapper
				) }
			>
				{ /* Dropdown Items */ }
				{ !! childrenCount && renderChildren }

				{ /* No items found */ }
				{ ! childrenCount && (
					<div
						className={ cn(
							'p-2 text-center font-medium text-field-placeholder',
							selectItemClassNames[ sizeValue as SelectSizes ]
						) }
					>
						No items found
					</div>
				) }
			</div>
		</div>
	);

	return (
		<>
			{ /* Dropdown */ }
			{ isOpen && (
				<>
					{ inlineSearch ? (
						dropdownContent
					) : (
						<FloatingFocusManager
							context={ context }
							modal={ false }
							visuallyHiddenDismiss
						>
							{ dropdownContent }
						</FloatingFocusManager>
					) }
				</>
			) }
		</>
	);
}

export function SelectPortal( { children, root, id }: SelectPortalProps ) {
	return (
		<FloatingPortal id={ id } root={ root }>
			{ children }
		</FloatingPortal>
	);
}

export function SelectItem( {
	value,
	selected,
	children,
	className,
	...props
}: SelectOptionProps ) {
	const {
		sizeValue,
		getItemProps,
		onKeyDownItem,
		onClickItem,
		activeIndex,
		selectedIndex,
		updateListRef,
		getValues,
		by,
		multiple,
		inlineSearch,
	} = useSelectContext();
	const { index: indx, id: optionId } = props as {
		index: number;
		id?: string;
		[key: string]: unknown;
	};
	const initialIndxRef = useRef( indx );

	const selectedIconClassName = {
		sm: 'size-4',
		md: 'size-4',
		lg: 'size-5',
	};

	const multipleChecked = useMemo( () => {
		if ( ! multiple ) {
			return false;
		}
		const currentValue = getValues();
		if ( ! currentValue ) {
			return false;
		}
		return ( currentValue as SelectOptionValue[] ).some( ( val ) => {
			if ( val !== null && value !== null && typeof val === 'object' ) {
				return (
					( val as Record<string, unknown> )[ by ] ===
					( value as Record<string, unknown> )[ by ]
				);
			}
			return val === value;
		} );
	}, [ value, getValues ] );

	const isChecked = useMemo( () => {
		if ( typeof selected === 'boolean' ) {
			return selected;
		}

		if ( multiple ) {
			return multipleChecked;
		}

		return indx === selectedIndex;
	}, [ multipleChecked, selectedIndex, selected ] );

	let itemTabIndex: number | undefined;
	if ( ! inlineSearch ) {
		itemTabIndex = indx === activeIndex ? 0 : -1;
	}

	return (
		<div
			id={ optionId }
			className={ cn(
				'w-full flex items-center justify-between text-text-primary hover:bg-button-tertiary-hover rounded-md transition-all duration-150 cursor-pointer focus:outline-none focus-within:outline-none outline-none',
				selectItemClassNames[ sizeValue as SelectSizes ],
				indx === activeIndex && 'bg-button-tertiary-hover',
				className
			) }
			ref={ ( node ) => {
				updateListRef( indx as number, node as HTMLElement );
			} }
			role="option"
			tabIndex={ itemTabIndex }
			aria-selected={ isChecked && indx === activeIndex }
			{ ...getItemProps( {
				// Handle pointer select.
				onClick() {
					onClickItem( initialIndxRef.current as number, value );
				},
				// Handle keyboard select.
				onKeyDown( event: React.KeyboardEvent ) {
					onKeyDownItem(
						event,
						initialIndxRef.current as number,
						value
					);
				},
			} ) }
		>
			<span className="w-full truncate">{ children }</span>
			{ isChecked && (
				<CheckIcon
					className={ cn(
						'text-icon-on-color-disabled',
						selectedIconClassName[ sizeValue as SelectSizes ]
					) }
				/>
			) }
		</div>
	);
}

const SelectComponent = ( {
	id,
	size: sizeValue = 'md', // sm, md, lg
	value, // Value of the select (for controlled component).
	defaultValue, // Default value of the select (for uncontrolled component).
	onChange, // Callback function to handle the change event.
	by = 'id', // Used to identify the select component. Default is 'id'.
	children,
	multiple = false, // If true, it will allow multiple selection.
	combobox = false, // If true, it will show a search box.
	inlineSearch = false, // If true, renders search input inside the trigger.
	disabled = false, // If true, it will disable the select component.
	searchPlaceholder = 'Search...', // Placeholder text for search box.
	searchFn, // Function to handle the search.
	debounceDelay = 500, // Debounce delay for the search.
}: SelectProps ) => {
	const selectId = useMemo( () => id || `select-${ nanoid() }`, [ id ] );
	const isControlled = useMemo( () => typeof value !== 'undefined', [ value ] );

	if ( process.env.NODE_ENV !== 'production' && combobox && inlineSearch ) {
		// eslint-disable-next-line no-console
		console.warn(
			'force-ui Select: `inlineSearch` and `combobox` are mutually exclusive. `inlineSearch` will take precedence.'
		);
	}
	const [ selected, setSelected ] = useState<
		SelectOptionValue | SelectOptionValue[]
	>( defaultValue! );
	const [ searchKeyword, setSearchKeyword ] = useState( '' );

	const getValues = useCallback<SelectGetValues>( () => {
		if ( isControlled ) {
			return value as string | number | Record<string, unknown>;
		}
		return selected as string | number | Record<string, unknown>;
	}, [ isControlled, value, selected ] );

	// Dropdown position related code (Start)
	const [ isOpen, setIsOpen ] = useState( false );
	const [ activeIndex, setActiveIndex ] = useState<number | null>( null );
	const [ selectedIndex, setSelectedIndex ] = useState<number | null>( null );

	const dropdownMaxHeightBySize = {
		sm: combobox && ! inlineSearch ? 256 : 172,
		md: combobox && ! inlineSearch ? 256 : 216,
		lg: combobox && ! inlineSearch ? 256 : 216,
	};

	const { refs, floatingStyles, context } = useFloating( {
		strategy: 'fixed',
		placement: 'bottom-start',
		open: isOpen,
		onOpenChange: setIsOpen,
		whileElementsMounted: autoUpdate,
		middleware: [
			offset( 5 ),
			flip( { padding: 10 } ),
			size( {
				apply( { rects, elements, availableHeight } ) {
					Object.assign( elements.floating.style, {
						maxHeight: `min(${ availableHeight }px, ${ dropdownMaxHeightBySize[ sizeValue as SelectSizes ] }px)`,
						maxWidth: `${ rects.reference.width }px`,
					} );
				},
				padding: 10,
			} ),
		],
	} );

	const listRef = useRef<Array<HTMLElement | null>>( [] );
	const listContentRef = useRef( [] );
	const isTypingRef = useRef( false );
	const optionValuesRef = useRef<SelectOptionValue[]>( [] );

	// Clear search when dropdown closes (Escape, outside-click, or selection).
	useEffect( () => {
		if ( ! isOpen ) {
			setSearchKeyword( '' );
		}
	}, [ isOpen ] );

	const click = useClick( context, {
		event: 'mousedown',
		enabled: ! inlineSearch,
	} );
	const dismiss = useDismiss( context );
	const role = useRole( context, { role: 'listbox' } );
	const listNav = useListNavigation( context, {
		listRef,
		activeIndex,
		selectedIndex,
		onNavigate: setActiveIndex,
		loop: true,
		// virtual: input is the reference, items use aria-activedescendant rather than DOM focus.
		virtual: inlineSearch,
	} );
	const typeahead = useTypeahead( context, {
		listRef: listContentRef,
		activeIndex,
		selectedIndex,
		onMatch: isOpen ? setActiveIndex : setSelectedIndex,
		onTypingChange( isTyping ) {
			isTypingRef.current = isTyping;
		},
	} );

	const { getReferenceProps, getFloatingProps, getItemProps } =
		useInteractions( [
			dismiss,
			role,
			listNav,
			click,
			...( ! combobox && ! inlineSearch ? [ typeahead ] : [] ),
		] );

	const handleMultiSelect: OnClick = ( index, newValue ) => {
		const selectedValues = [
			...( ( getValues() as SelectOptionValue[] ) ?? [] ),
		];
		const valueIndex = selectedValues.findIndex( ( selectedValue ) => {
			if (
				selectedValue !== null &&
				newValue !== null &&
				typeof selectedValue === 'object'
			) {
				return (
					( selectedValue as Record<string, unknown> )[ by ] ===
					( newValue as Record<string, unknown> )[ by ]
				);
			}
			return selectedValue === newValue;
		} );

		if ( valueIndex !== -1 ) {
			return;
		}
		selectedValues.push( newValue );

		if ( ! isControlled ) {
			setSelected( selectedValues );
		}
		setSelectedIndex( index );
		(
			( refs.domReference.current ??
				refs.reference.current ) as HTMLElement | null
		)?.focus();
		setIsOpen( false );
		setSearchKeyword( '' );
		if ( typeof onChange === 'function' ) {
			onChange( selectedValues );
		}
	};

	const handleSelect: OnClick = ( index, newValue ) => {
		if ( multiple ) {
			return handleMultiSelect( index, newValue );
		}
		setSelectedIndex( index );
		if ( ! isControlled ) {
			setSelected( newValue );
		}
		(
			( refs.domReference.current ??
				refs.reference.current ) as HTMLElement | null
		)?.focus();
		setIsOpen( false );
		setSearchKeyword( '' );
		if ( typeof onChange === 'function' ) {
			onChange( newValue );
		}
	};
	// Dropdown position related code (End)

	const updateListRef = useCallback( ( index: number, node: HTMLElement ) => {
		listRef.current[ index ] = node;
	}, [] );

	const onClickItem: OnClick = ( index, newValue ) => {
		handleSelect( index, newValue );
	};

	const onKeyDownItem: OnKeyDown = ( event, index, newValue ) => {
		if ( event.key === 'Enter' ) {
			event.preventDefault();
			handleSelect( index, newValue );
		}

		if ( event.key === ' ' && ! isTypingRef.current ) {
			event.preventDefault();
			handleSelect( index, newValue );
		}
	};

	return (
		<SelectContext.Provider
			value={ {
				selectedIndex,
				setSelectedIndex,
				activeIndex,
				setActiveIndex,
				selected,
				setSelected,
				handleSelect,
				combobox,
				inlineSearch,
				optionValuesRef,
				sizeValue,
				multiple,
				onChange,
				isTypingRef,
				getItemProps,
				onClickItem,
				onKeyDownItem,
				getValues,
				selectId,
				getReferenceProps,
				isOpen,
				value,
				updateListRef,
				refs,
				listContentRef,
				by,
				getFloatingProps,
				floatingStyles,
				context,
				searchKeyword,
				setSearchKeyword,
				disabled,
				isControlled,
				searchPlaceholder,
				searchFn,
				debounceDelay,
			} }
		>
			{ children }
		</SelectContext.Provider>
	);
};

SelectComponent.displayName = 'Select';

const Select = Object.assign( SelectComponent, {
	Portal: SelectPortal,
	Button: SelectButton,
	Options: SelectOptions,
	Option: SelectItem,
	OptionGroup: SelectOptionGroup,
} );

SelectPortal.displayName = 'Select.Portal';
SelectButton.displayName = 'Select.Button';
SelectOptions.displayName = 'Select.Options';
SelectItem.displayName = 'Select.Option';
SelectOptionGroup.displayName = 'Select.OptionGroup';

export default Select;
